  --vd-primary-5: var(--vd-oc-primary-5);
}

/* Or address either palette's raw scale directly */
.swatch-oc  { background: var(--vd-oc-primary-5); }   /* Open Color */
.swatch-fib { background: var(--vd-fib-primary-5); }  /* Fibonacci  */

