import { ref } from 'vue';
import { useSidenav } from "@vanduo-oss/vd3";

const root = ref<HTMLElement | null>(null);
useSidenav(root);   // wires [data-sidenav-toggle] triggers; cleanup on unmount

import { ref } from 'vue';
import { useSpotlight } from "@vanduo-oss/vd3";

const root = ref<HTMLElement | null>(null);
useSpotlight(root);   // wires every [data-vd-spotlight] inside root

import { ref } from 'vue';
import { useStepper } from "@vanduo-oss/vd3";

const root = ref<HTMLElement | null>(null);
const stepper = useStepper(root);   // wires .vd-stepper (+ clickable / animated) inside root

// drive it imperatively
stepper.next(stepperEl);
stepper.setStep(stepperEl, 2);

// Markup: add .vd-stepper-animated for staggered reveal,
// .vd-stepper-clickable for click/keyboard navigation (any orientation).

import { ref } from 'vue';
import { useAffix } from "@vanduo-oss/vd3";

const root = ref<HTMLElement | null>(null);
useAffix(root);   // wires .vd-affix / [data-vd-affix] inside root; cleanup on unmount

// react to pin / unpin
root.value?.addEventListener('affix:stuck', () => { /* … */ });

import { ref } from 'vue';
import { useTabs } from "@vanduo-oss/vd3";

const root = ref<HTMLElement | null>(null);
useTabs(root);   // wires [data-tab-target] inside root; cleanup on unmount

import { ref } from "vue";
import { VdThemeCustomizer } from "@vanduo-oss/vd3";

const customizer = ref<InstanceType<typeof VdThemeCustomizer>>();

// Drive a specific instance via its exposed methods:
customizer.value?.open();
customizer.value?.close();
customizer.value?.toggle();

// …or open any mounted instance from anywhere via the window event
// (e.g. a navbar button):
window.dispatchEvent(new CustomEvent("vd:open-customizer"));

import { useThemePreference } from "@vanduo-oss/vd3";
const theme = useThemePreference();

// Reactive current state (six fields):
theme.state.palette; theme.state.primary; theme.state.neutral;
theme.state.radius;  theme.state.font;    theme.state.theme;

// Setters — each persists to localStorage + applies to <html>:
theme.setPalette("fibonacci");
theme.setPrimary("violet");
theme.setNeutral("slate");
theme.setRadius("0.375");
theme.setFont("open-sans");
theme.setTheme("dark");

// Reset every field to the defaults:
theme.reset();

// vd3 theming is a reactive singleton, not global JS calls
import { useThemePreference } from '@vanduo-oss/vd3';

const theme = useThemePreference();
theme.setTheme('dark');       // 'system' | 'light' | 'dark'
theme.setPalette('fibonacci'); // 'open-color' | 'fibonacci'
theme.setPrimary('violet');   // brand hue
theme.setNeutral('slate');    // neutral ramp
theme.setRadius('0.5');       // corner radius scale
theme.setFont('lato');        // base font family
theme.reset();                // back to defaults

// Preferences persist in localStorage and re-hydrate automatically.
// Keys follow storagePrefix (default "vanduo-"):
//   {prefix}palette, {prefix}primary-color, {prefix}neutral-color,
//   {prefix}radius, {prefix}font-preference, {prefix}theme-preference
// Example with the default prefix: vanduo-theme-preference
// Pass storagePrefix to VanduoVue when two apps share an origin.
// useThemePreference() reads them on first client access — there is no init().

import { VanduoVue, setThemeDefaults } from "@vanduo-oss/vd3";

// Option A — pass themeDefaults to the plugin once, at bootstrap:
app.use(VanduoVue, {
  themeDefaults: {
    PRIMARY_LIGHT: "black",
    PRIMARY_DARK: "green",
  },
});

// Option B — call the helper directly, before the theme first reads defaults:
setThemeDefaults({ PRIMARY_DARK: "violet" });

import { ref } from 'vue';
import { useTimeline } from "@vanduo-oss/vd3";

const root = ref<HTMLElement | null>(null);
useTimeline(root);   // wires every .vd-timeline-animated inside root

import { ref } from 'vue';
import { useTimepicker } from "@vanduo-oss/vd3";

const root = ref<HTMLElement | null>(null);
useTimepicker(root);   // wires [data-vd-timepicker] inside root; cleanup on unmount

// react to a time being chosen
root.value?.addEventListener('timepicker:select', (e) => {
  console.log(e.detail.time, e.detail.hours, e.detail.minutes);
});

