import { ref } from 'vue';
import { useTooltips } from "@vanduo-oss/vd3";

const root = ref<HTMLElement | null>(null);

// wires [data-tooltip] inside root; cleanup on unmount
useTooltips(root);

// …or dwell 520ms before showing (dock and toolbar chrome)
useTooltips(root, { showDelay: 520 });

import { ref } from 'vue';

const transferRef = ref();

// Read the current Target-panel ids via the exposed method:
const selected = transferRef.value?.getSelected();
console.log(selected); // ["javascript", "python"]

// VdTransfer also dispatches a native transfer:change event
// ({ selected, available }) on its root — listen via a template ref.

Event | Description
tree:check | Fired on the element when a checkbox changes. event.detail contains { checked: string[], node: string }
tree:toggle | Fired when a node is expanded or collapsed. event.detail contains { id: string, open: boolean }

import { ref } from 'vue';

const treeRef = ref();

// Get all checked node IDs via the exposed method
const checked = treeRef.value?.getChecked();
console.log(checked); // ["users-read", "users-create"]

// VdTree also dispatches a native tree:check event
// ({ checked, node }) on its root — listen via a template ref.

